tool_use_result.originalFile:
/* 落点 · 选址对比台
 * 单屏选址决策：左地图语境 + 右比较矩阵 + 底部权重/落定条。
 * 全部数据内联，无网络请求，加载即 ready（无加载态）。
 * 状态模型：ready（初始）→ selected（选定候选）→ decided（落定，驻留同屏）。
 * loading / empty / error 为防御性守卫：数据内联故无加载与空态路径，初始化异常落入 #fatal 提示。
 */
'use strict';

/* ── 数据（内联，示意数据） ─────────────────────────────── */

const CATS = [
  { id: 'price',   label: '价格' },
  { id: 'commute', label: '通勤' },
  { id: 'space',   label: '空间' },
  { id: 'quiet',   label: '安静' },
  { id: 'light',   label: '采光' },
  { id: 'quality', label: '品质' },
];

const DIMS = {
  rent:    { label: '月租', unit: '元 / 月', cat: 'price', num: true, dir: 'low',  win: c => `月租最低 ¥${c.v.rent.toLocaleString('zh-CN')}` },
  commute: { label: '通勤 · 到公司', unit: '分钟 · 门到门', cat: 'commute', num: true, dir: 'low', win: c => `通勤最短（${c.v.commute} 分钟）` },
  deposit: { label: '押付方式', cat: 'price', win: c => `押付最轻（${c.t.deposit}）` },
  area:    { label: '面积', unit: '㎡', cat: 'space', num: true, dir: 'high', win: c => `面积最大（${c.v.area} ㎡）` },
  layout:  { label: '户型', cat: 'space', win: () => '户型最完整' },
  noise:   { label: '噪音 · 昼间', unit: 'dB', cat: 'quiet', num: true, dir: 'low', win: c => `最安静（${c.v.noise} dB）` },
  light:   { label: '采光', cat: 'light', win: () => '采光最优' },
  age:     { label: '楼龄', unit: '年', cat: 'quality', num: true, dir: 'low', win: c => `楼龄最新（${c.v.age} 年）` },
  floor:   { label: '楼层 · 电梯', cat: 'quality', win: () => '梯户条件最优' },
  nearby:  { label: '周边配套', cat: 'quality', win: () => '日常配套最全' },
};
Object.keys(DIMS).forEach(id => { DIMS[id].id = id; }); // 维度对象自带 id（键与字段同步）

const GROUPS = [
  { label: '成本与通勤', dims: ['rent', 'commute', 'deposit'] },
  { label: '空间与舒适', dims: ['area', 'layout', 'noise', 'light'] },
  { label: '楼况与配套', dims: ['age', 'floor', 'nearby'] },
];

const CANDIDATES = [
  { id: 'c1', name: '望江里 · B 座', color: 'var(--c1)', tag: '临街高层 · 江景', map: { x: 336, y: 168 },
    v: { rent: 3580, commute: 32, area: 45, noise: 62, age: 3 },
    q: { deposit: 5, layout: 3, light: 5, floor: 4, nearby: 4 },
    t: { deposit: '押一付一', layout: '一室一厅', light: '东南向 · 充足', floor: '14/26 · 双电梯',
         nearby: '菜场 300m · 健身 450m', noiseTag: '临街', commuteNote: '公交 2 站 + 步行 600m' } },
  { id: 'c2', name: '榕树苑 · 3 栋', color: 'var(--c2)', tag: '公园旁 · 低密院落', map: { x: 140, y: 330 },
    v: { rent: 4200, commute: 18, area: 62, noise: 48, age: 12 },
    q: { deposit: 2, layout: 5, light: 4, floor: 4, nearby: 5 },
    t: { deposit: '押一付三', layout: '两室一厅', light: '南向 · 院景', floor: '6/11 · 电梯',
         nearby: '公园即达 · 菜场 150m', noiseTag: '围合院内', commuteNote: '地铁 4 站直达' } },
  { id: 'c3', name: '科苑馨庭', color: 'var(--c3)', tag: '地铁上盖 · 商圈', map: { x: 250, y: 398 },
    v: { rent: 3250, commute: 25, area: 38, noise: 58, age: 8 },
    q: { deposit: 3, layout: 2, light: 2, floor: 3, nearby: 3 },
    t: { deposit: '押二付一', layout: '开间', light: '北向 · 一般', floor: '22/30 · 电梯',
         nearby: '商场楼下 · 菜场 700m', noiseTag: '地铁上盖', commuteNote: '地铁 6 站' } },
  { id: 'c4', name: '永安坊 · 西院', color: 'var(--c4)', tag: '老城厢 · 带书房', map: { x: 84, y: 96 },
    v: { rent: 3890, commute: 41, area: 54, noise: 49, age: 21 },
    q: { deposit: 2, layout: 4, light: 3, floor: 2, nearby: 4 },
    t: { deposit: '押一付三', layout: '一室一厅 + 书房', light: '西向 · 午后光', floor: '3/6 · 无电梯',
         nearby: '老城商圈 · 医院 200m', noiseTag: '巷内', commuteNote: '公交两程 + 步行' } },
];

/* 通勤线路（自绘 SVG 路径）与时长标签位置 */
const ROUTES = {
  c1: { d: 'M336,168 C320,196 284,202 257,207', lx: 302, ly: 192 },
  c2: { d: 'M140,330 C168,292 220,242 250,213', lx: 176, ly: 268 },
  c3: { d: 'M250,398 C246,340 252,262 251,213', lx: 238, ly: 320 },
  c4: { d: 'M84,96 C118,142 202,192 249,207',   lx: 136, ly: 152 },
};

const PRESETS = {
  均衡:     { price: 4, commute: 4, space: 3, quiet: 3, light: 2, quality: 2 },
  省钱优先: { price: 5, commute: 2, space: 2, quiet: 3, light: 1, quality: 2 },
  通勤优先: { price: 2, commute: 5, space: 2, quiet: 3, light: 2, quality: 1 },
  品质优先: { price: 2, commute: 3, space: 5, quiet: 4, light: 4, quality: 5 },
};

/* ── 状态（会话内；按交付约束不做跨会话持久化） ───────────── */

const state = {
  weights: { ...PRESETS.均衡 },
  selected: null,   // selected 态：列头/图钉联动高亮
  decided: null,    // decided 态：落定，驻留同屏
};

const $ = (sel, root) => (root || document).querySelector(sel);
const byId = id => CANDIDATES.find(c => c.id === id);
const SVGNS = 'http://www.w3.org/2000/svg';

/* ── 评分模型：维度归一 0–100 → 类别均值 → 加权总分 ─────────── */

function normFor(dim, cand) {
  if (!dim.num) return (cand.q[dim.id] - 1) / 4 * 100;
  const vals = CANDIDATES.map(c => c.v[dim.id]);
  const best = Math.max(...vals), worst = Math.min(...vals);
  if (best === worst) return 100;
  const v = cand.v[dim.id];
  return dim.dir === 'low' ? (worst - v) / (worst - best) * 100 : (v - worst) / (best - worst) * 100;
}

function computeScores() {
  let ws = CATS.map(c => state.weights[c.id]);
  const allZero = ws.every(w => w === 0);
  const out = {};
  CANDIDATES.forEach(cand => {
    let sum = 0, wsum = 0;
    CATS.forEach(cat => {
      const dims = GROUPS.flatMap(g => g.dims).map(id => DIMS[id]).filter(d => d.cat === cat.id);
      const mean = dims.reduce((a, d) => a + normFor(d, cand), 0) / dims.length;
      const w = allZero ? 1 : state.weights[cat.id];
      sum += w * mean; wsum += w;
    });
    out[cand.id] = Math.round(sum / wsum);
  });
  return out;
}

const rankedIds = scores => CANDIDATES.map(c => c.id).sort((a, b) => scores[b] - scores[a]);

function reasonFor(cand, scores) {
  const allDims = GROUPS.flatMap(g => g.dims).map(id => DIMS[id]);
  const wins = allDims
    .filter(d => normFor(d, cand) === 100)
    .sort((a, b) => state.weights[b.cat] - state.weights[a.cat])
    .slice(0, 3)
    .map(d => d.win(cand));
  return wins.length ? wins.join(' · ') : `综合加权 ${scores[cand.id]} 分`;
}

/* ── 构建：表头（一次性，之后只切换状态类） ─────────────────── */

function buildHead() {
  const row = $('#head-row');
  CANDIDATES.forEach(c => {
    const th = document.createElement('th');
    th.scope = 'col';
    th.className = 'cand-head';
    th.dataset.col = c.id;
    th.style.setProperty('--pin', c.color);
    th.innerHTML =
      `<div class="ch-top">` +
      `<span class="pin-dot" style="background:${c.color}"></span>` +
      `<div><div class="ch-name">${c.name}</div><div class="ch-tag">${c.tag}</div></div>` +
      `<button class="btn-select" data-select="${c.id}" aria-pressed="false" title="选定 ${c.name}">选定</button>` +
      `<span class="badge-decided" data-badge="${c.id}">已落定 ✓</span>` +
      `</div>`;
    th.addEventListener('click', e => { if (!e.target.closest('button')) select(c.id); });
    row.appendChild(th);
  });
  row.addEventListener('click', e => {
    const btn = e.target.closest('button[data-select]');
    if (btn) select(btn.dataset.select);
  });
}

/* ── 构建：比较矩阵主体（重渲染，量小无性能负担） ───────────── */

function miniBar(dim, c) {
  if (!dim.num) return '';
  const n = Math.round(normFor(dim, c));
  return `<span class="mini-bar" aria-hidden="true"><i style="width:${n}%;background:${c.color}"></i></span>`;
}

function cellHTML(dim, c) {
  switch (dim.id) {
    case 'rent':    return `<span class="cell-val">¥${c.v.rent.toLocaleString('zh-CN')}</span>` + miniBar(dim, c);
    case 'commute': return `<span class="cell-val">${c.v.commute} 分</span><span class="cell-sub">${c.t.commuteNote}</span>` + miniBar(dim, c);
    case 'area':    return `<span class="cell-val">${c.v.area} ㎡</span>` + miniBar(dim, c);
    case 'noise':   return `<span class="cell-val">${c.v.noise} dB</span><span class="cell-sub">${c.t.noiseTag}</span>` + miniBar(dim, c);
    case 'age':     return `<span class="cell-val">${c.v.age} 年</span>` + miniBar(dim, c);
    default:        return `<span class="cell-val">${c.t[dim.id]}</span>`;
  }
}

function renderBody() {
  const tbody = $('#tbody');
  const scores = computeScores();
  const ranks = {};
  rankedIds(scores).forEach((id, i) => { ranks[id] = i + 1; });
  const rec = rankedIds(scores)[0];

  if (!CANDIDATES.length) { // 防御性空态（数据内联，正常不可达）
    tbody.innerHTML = '<tr><td colspan="5">暂无候选地点。</td></tr>';
    return;
  }

  let html = '<tr class="row-score"><th scope="row">加权总分<small>随偏好权重实时更新</small></th>';
  CANDIDATES.forEach(c => {
    html += `<td data-col="${c.id}">` +
      `<span class="score-num">${scores[c.id]}</span>` +
      `<span class="rank-chip${ranks[c.id] === 1 ? ' r1' : ''}" title="当前排名">第 ${ranks[c.id]}</span>` +
      (ranks[c.id] === 1 ? '<span class="pill-rec">推荐</span>' : '') +
      `<span class="score-bar" aria-hidden="true"><i style="width:${scores[c.id]}%;background:${c.color}"></i></span>` +
      `</td>`;
  });
  html += '</tr>';

  GROUPS.forEach(g => {
    html += `<tr class="g"><th colspan="5" scope="colgroup">${g.label}</th></tr>`;
    g.dims.forEach(dimId => {
      const dim = DIMS[dimId];
      html += `<tr><th scope="row">${dim.label}<small>${dim.unit || '定性评估'}</small></th>`;
      CANDIDATES.forEach(c => {
        const n = normFor(dim, c);
        const cls = (n === 100 ? 'best' : n === 0 ? 'worst' : '');
        html += `<td data-col="${c.id}"${cls ? ` class="${cls}"` : ''}>` +
          cellHTML(dim, c) +
          (n === 100 ? '<span class="tag-best">优</span>' : '') +
          `</td>`;
      });
      html += '</tr>';
    });
  });

  tbody.innerHTML = html;
  tbody.dataset.rec = rec;
}

/* ── 构建：权重滑杆与预设 ─────────────────────────────────── */

function buildWeights() {
  const wrap = $('#sliders');
  CATS.forEach(cat => {
    const g = document.createElement('span');
    g.className = 'wg';
    g.innerHTML =
      `<label for="w-${cat.id}">${cat.label}</label>` +
      `<input type="range" id="w-${cat.id}" min="0" max="5" step="1" value="${state.weights[cat.id]}" aria-label="${cat.label}权重（0 至 5）">` +
      `<output for="w-${cat.id}">×${state.weights[cat.id]}</output>`;
    wrap.appendChild(g);
  });
  wrap.addEventListener('input', e => {
    const inp = e.target.closest('input[type=range]');
    if (!inp) return;
    const catId = inp.id.slice(2);
    state.weights[catId] = Number(inp.value);
    inp.nextElementSibling.textContent = `×${inp.value}`;
    refreshScores();
  });

  const pre = $('#presets');
  Object.keys(PRESETS).forEach(name => {
    const b = document.createElement('button');
    b.className = 'btn-preset';
    b.textContent = name;
    b.dataset.preset = name;
    b.title = name === '均衡' ? '重置为均衡权重' : `应用预设：${name}`;
    pre.appendChild(b);
  });
  pre.addEventListener('click', e => {
    const b = e.target.closest('button[data-preset]');
    if (!b) return;
    state.weights = { ...PRESETS[b.dataset.preset] };
    CATS.forEach(cat => {
      const inp = $(`#w-${cat.id}`);
      inp.value = state.weights[cat.id];
      inp.nextElementSibling.textContent = `×${state.weights[cat.id]}`;
    });
    refreshScores();
  });
}

function refreshPresets() {
  document.querySelectorAll('.btn-preset').forEach(b => {
    const p = PRESETS[b.dataset.preset];
    b.classList.toggle('on', CATS.every(c => p[c.id] === state.weights[c.id]));
  });
}

/* ── 构建：地图图钉 / 通勤线路 / 图例 ─────────────────────── */

function svgEl(tag, attrs) {
  const n = document.createElementNS(SVGNS, tag);
  for (const k in attrs) n.setAttribute(k, attrs[k]);
  return n;
}

function buildMap() {
  const pins = $('#pins'), routes = $('#routes');
  CANDIDATES.forEach(c => {
    const r = ROUTES[c.id];
    const g = svgEl('g', { class: 'route-g', 'data-route': c.id });
    g.appendChild(svgEl('path', { class: 'route', d: r.d, stroke: c.color }));
    const t = svgEl('text', { class: 'route-min', x: r.lx, y: r.ly, fill: c.color, 'text-anchor': 'middle' });
    t.textContent = `${c.v.commute}分`;
    g.appendChild(t);
    routes.appendChild(g);

    const p = svgEl('g', {
      class: 'pin', 'data-pin': c.id, tabindex: '0', role: 'button',
      'aria-pressed': 'false', 'aria-label': `在地图上选定 ${c.name}`,
    });
    p.appendChild(svgEl('ellipse', { class: 'pin-shadow', cx: c.map.x, cy: c.map.y + 14, rx: 6, ry: 2.5 }));
    p.appendChild(svgEl('circle', { class: 'pin-ring', cx: c.map.x, cy: c.map.y, r: 15 }));
    p.appendChild(svgEl('circle', { class: 'pin-body', cx: c.map.x, cy: c.map.y, r: 11, fill: c.color }));
    const num = svgEl('text', { class: 'pin-num', x: c.map.x, y: c.map.y + 4 });
    num.textContent = c.id.slice(1);
    p.appendChild(num);
    const label = svgEl('text', { class: 'pin-label', x: c.map.x, y: c.map.y + 28 });
    label.textContent = c.name;
    p.appendChild(label);
    p.addEventListener('click', () => select(c.id));
    p.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(c.id); }
    });
    pins.appendChild(p);
  });

  const legend = $('#legend');
  legend.innerHTML =
    CANDIDATES.map(c => `<span class="lg"><i style="background:${c.color}"></i>${c.id.slice(1)} ${c.name}</span>`).join('') +
    `<span class="lg"><i class="lg-office"></i>公司 · 科苑大厦</span>` +
    `<span class="lg"><i class="lg-line"></i>地铁 7 号线</span>`;
}

/* ── 状态渲染：选中 / 落定 驻留同屏 ───────────────────────── */

function select(id) {
  state.selected = id;
  renderAll();
}

function renderStates() {
  const scores = computeScores();

  document.querySelectorAll('#cmp [data-col]').forEach(cell => {
    const id = cell.dataset.col;
    cell.classList.toggle('col-sel', state.selected === id && state.decided !== id);
    cell.classList.toggle('col-decided', state.decided === id);
  });
  document.querySelectorAll('#head-row .cand-head').forEach(th => {
    const id = th.dataset.col;
    th.classList.toggle('col-sel', state.selected === id && state.decided !== id);
    th.classList.toggle('col-decided', state.decided === id);
    const btn = th.querySelector('.btn-select');
    btn.setAttribute('aria-pressed', String(state.selected === id));
    btn.textContent = state.selected === id ? '已选定' : '选定';
    th.querySelector('.badge-decided').style.display = state.decided === id ? 'inline-block' : 'none';
    btn.style.display = state.decided === id ? 'none' : '';
  });
  document.querySelectorAll('.pin').forEach(p => {
    const id = p.dataset.pin;
    p.classList.toggle('sel', state.selected === id && state.decided !== id);
    p.classList.toggle('decided', state.decided === id);
    p.setAttribute('aria-pressed', String(state.selected === id || state.decided === id));
  });
  document.querySelectorAll('.route-g').forEach(g => {
    g.querySelector('.route').classList.toggle('hot', g.dataset.route === state.selected || g.dataset.route === state.decided);
    g.querySelector('.route-min').classList.toggle('hot', g.dataset.route === state.selected || g.dataset.route === state.decided);
  });

  /* 顶栏状态 */
  const hdr = $('#hdr-status');
  if (state.decided) {
    const c = byId(state.decided);
    hdr.innerHTML = `<span class="chip decided"><span class="dot" style="background:${c.color}"></span>已落定 · ${c.name}</span>`;
  } else {
    hdr.innerHTML = '<span class="chip">未落定 · 比较后选定候选</span>';
  }

  /* 底部落定面板（唯一常驻主操作） */
  const panel = $('#decide-panel');
  const rec = rankedIds(scores)[0];
  if (state.decided) {
    const c = byId(state.decided);
    panel.classList.add('decided');
    panel.innerHTML =
      `<div class="dp-info"><div class="dp-title">已落定 · 决策驻留同屏</div>` +
      `<div class="dp-main">${c.name} · ${scores[c.id]} 分</div>` +
      `<div class="dp-reason">${reasonFor(c, scores)}</div></div>` +
      `<button class="btn-primary" id="btn-redecide">重新比较</button>`;
    $('#btn-redecide').addEventListener('click', () => { state.decided = null; renderAll(); });
  } else if (state.selected) {
    const c = byId(state.selected);
    const isRec = state.selected === rec;
    panel.classList.remove('decided');
    panel.innerHTML =
      `<div class="dp-info"><div class="dp-title">已选定 · 待落定</div>` +
      `<div class="dp-main">${c.name} · ${scores[c.id]} 分${isRec ? ' · 当前推荐' : `（推荐：${byId(rec).name}）`}</div>` +
      `<div class="dp-reason">${reasonFor(c, scores)}</div></div>` +
      `<button class="btn-primary" id="btn-decide">落定：${c.name.split(' · ')[0]}</button>`;
    $('#btn-decide').addEventListener('click', () => { state.decided = state.selected; renderAll(); });
  } else {
    panel.classList.remove('decided');
    panel.innerHTML =
      `<div class="dp-info"><div class="dp-title">尚未选定</div>` +
      `<div class="dp-main">当前推荐：${byId(rec).name} · ${scores[rec]} 分</div>` +
      `<div class="dp-reason">点击列头「选定」或地图图钉，再一键落定</div></div>` +
      `<button class="btn-primary" id="btn-decide" disabled>落定</button>`;
  }
}

function renderAll() {
  renderBody();
  refreshPresets();
  renderStates();
}

function refreshScores() { /* 权重变化：无需重建表头/图钉 */
  renderBody();
  refreshPresets();
  renderStates();
}

/* ── 证据辅助：#select=c2&decide=c2 可复现状态截图（不影响正常流程） ── */

function applyUrlParams() {
  const raw = location.hash.startsWith('#') ? location.hash.slice(1) : location.search.slice(1);
  const q = new URLSearchParams(raw);
  const d = q.get('decide'), s = q.get('select');
  if (d && byId(d)) { state.decided = d; state.selected = d; }
  else if (s && byId(s)) { state.selected = s; }
}

/* ── 初始化（同步完成：加载即 ready） ─────────────────────── */

function init() {
  buildHead();
  buildWeights();
  buildMap();
  applyUrlParams();
  renderAll();
}

try {
  init();
} catch (err) {
  const f = $('#fatal');
  f.hidden = false;
  f.textContent = `初始化失败：${err && err.message ? err.message : err}`;
}

/* 落点 · 选址对比台 — design tokens（H-23 AA 底线：正文对比 ≥ 4.5:1，字号 ≥ 12px，保留焦点态） */
:root{
  --bg:#F3F1EA;
  --surface:#FFFFFF;
  --ink:#1B1E22;        /* 主文字 */
  --ink-2:#54595F;      /* 次文字（白底 ≈ 7:1） */
  --ink-3:#6E7278;      /* 辅助小字（白底 ≈ 5:1） */
  --line:#E3E0D6;
  --line-strong:#C8C4B6;
  --accent:#2F4E8E;
  --best-bg:#E4EFE0;
  --best-ink:#1E4D1B;
  --best-line:#B5CFAF;
  --ok-bg:#1E4D1B;
  --sel-bg:#FAF7EC;
  --c1:#A63A2E; --c2:#3E6B3A; --c3:#2F4E8E; --c4:#8A6210;
  --radius:8px;
  --shadow:0 1px 2px rgba(27,30,34,.06),0 4px 14px rgba(27,30,34,.05);
  --fs-base:13px; --fs-small:12px;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{
  font-family:"Segoe UI","Microsoft YaHei",system-ui,-apple-system,sans-serif;
  font-size:var(--fs-base); color:var(--ink); background:var(--bg);
  -webkit-font-smoothing:antialiased;
}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:4px}

#app{height:100vh;display:grid;grid-template-rows:auto minmax(0,1fr) auto}

/* ── 顶栏 ─────────────────────────────── */
#topbar{
  display:flex;align-items:center;justify-content:space-between;gap:16px;
  padding:10px 18px;background:var(--surface);border-bottom:1px solid var(--line-strong);
}
.brand h1{font-size:17px;letter-spacing:.5px}
.brand-sub{margin-left:8px;font-size:13px;font-weight:600;color:var(--ink-2)}
.brand .sub{font-size:var(--fs-small);color:var(--ink-3);margin-top:2px}
.hdr-status{flex-shrink:0}
.chip{
  display:inline-flex;align-items:center;gap:6px;padding:5px 12px;border-radius:999px;
  font-size:var(--fs-small);font-weight:600;border:1px solid var(--line-strong);color:var(--ink-2);background:var(--bg);
}
.chip.decided{background:var(--best-bg);border-color:var(--best-line);color:var(--best-ink)}
.chip .dot{width:8px;height:8px;border-radius:50%}

/* ── 主区：左地图 + 右比较矩阵 ─────────── */
#main{display:grid;grid-template-columns:378px minmax(0,1fr);min-height:0}
#map-pane{
  display:flex;flex-direction:column;min-height:0;
  border-right:1px solid var(--line-strong);background:var(--surface);
}
.pane-title{
  padding:8px 14px;font-weight:700;font-size:var(--fs-small);color:var(--ink);
  border-bottom:1px dashed var(--line);letter-spacing:.5px;
}
.pane-title-sub{margin-left:8px;font-weight:400;color:var(--ink-3)}
.map-wrap{flex:1;min-height:0;display:flex;justify-content:center;overflow:hidden;background:#EFEDE5}
#map{height:100%;width:100%;display:block}
.map-note{
  position:absolute;margin:8px;padding:3px 8px;font-size:var(--fs-small);color:var(--ink-3);
  background:rgba(255,255,255,.9);border-radius:6px;pointer-events:none;
}
.map-wrap{position:relative}
#legend{
  display:flex;flex-wrap:wrap;gap:4px 12px;padding:7px 14px;border-top:1px dashed var(--line);
  font-size:var(--fs-small);color:var(--ink-2);background:var(--surface);
}
.lg{display:inline-flex;align-items:center;gap:5px}
.lg i{width:10px;height:10px;border-radius:50%;display:inline-block}
.lg .lg-line{width:14px;height:0;border-top:3px solid #B45309;border-radius:2px}
.lg .lg-office{width:9px;height:8px;background:var(--ink);border-radius:2px}

/* 地图元素 */
.block{fill:#E7E4DA}
.water{fill:#C9DCE6}
.water-label{font-size:13px;fill:#4A7A93;font-weight:600}
.park{fill:#D6E3CB}
.tree{fill:#A9C29A}
.metro{fill:none;stroke:#B45309;stroke-width:5;stroke-linejoin:round;opacity:.85}
.metro-stn{fill:#fff;stroke:#B45309;stroke-width:2.5}
.metro-badge{
  font-size:12px;font-weight:800;fill:#fff;background:#B45309;
}
.metro-badge{fill:#B45309}
.metro-badge-bg{fill:#B45309}
.map-label{font-size:12px;fill:var(--ink);paint-order:stroke;stroke:rgba(255,255,255,.92);stroke-width:3px}
.park-label{fill:#3D5C36;font-weight:600}
.stn-label{fill:#7A4A0E;font-weight:600}
.office-label{font-weight:700}
.poi-dot{fill:var(--ink-2);stroke:#fff;stroke-width:1.5}
.poi-office{fill:var(--ink)}
.street-label{font-size:12px;fill:#8A8578;letter-spacing:2px}
.north-arrow{fill:var(--ink-2)}
.north-n{font-size:12px;fill:var(--ink-2);font-weight:700}

/* 通勤线路（JS 注入） */
.route{fill:none;stroke-width:2.5;stroke-dasharray:6 5;opacity:.32;stroke-linecap:round}
.route.hot{opacity:.95;stroke-width:3.5}
.route-min{
  font-size:12px;font-weight:700;paint-order:stroke;stroke:#fff;stroke-width:4px;
  display:none;
}
.route-min.hot{display:block}

/* 候选图钉（JS 注入） */
.pin{cursor:pointer}
.pin .pin-shadow{fill:rgba(27,30,34,.18)}
.pin .pin-body{stroke:#fff;stroke-width:2}
.pin .pin-num{font-size:12px;font-weight:800;fill:#fff;text-anchor:middle;pointer-events:none}
.pin .pin-label{
  font-size:12px;font-weight:700;fill:var(--ink);text-anchor:middle;
  paint-order:stroke;stroke:rgba(255,255,255,.95);stroke-width:3.5px;pointer-events:none;
}
.pin:focus-visible{outline:none}
.pin .pin-ring{fill:none;stroke:var(--accent);stroke-width:0;opacity:0}
.pin.sel .pin-ring{stroke-width:2.5;opacity:1}
.pin.sel .pin-body{stroke-width:3}
.pin.decided .pin-ring{stroke-width:3;opacity:1;stroke:var(--best-ink)}

/* ── 比较矩阵 ─────────────────────────── */
#table-pane{min-height:0;overflow:auto;background:var(--surface)}
#cmp{width:100%;border-collapse:separate;border-spacing:0;table-layout:fixed}
#cmp th,#cmp td{
  border-bottom:1px solid var(--line);padding:5px 10px;text-align:left;vertical-align:middle;
  transition:background .12s;
}
#cmp .dim-h,#cmp th[scope=row]{
  position:sticky;left:0;z-index:2;background:var(--surface);
  border-right:1px solid var(--line);
}
#cmp .dim-h{width:148px;font-size:var(--fs-small);color:var(--ink-3);font-weight:600;
  background:var(--surface);position:sticky;top:0;z-index:3}
#cmp thead th{position:sticky;top:0;z-index:3;background:var(--surface);border-bottom:1px solid var(--line-strong)}

/* 列头 */
.cand-head{cursor:pointer}
.cand-head .ch-top{display:flex;align-items:center;gap:8px}
.cand-head .pin-dot{width:12px;height:12px;border-radius:50%;flex-shrink:0;border:2px solid #fff;box-shadow:0 0 0 1px rgba(27,30,34,.25)}
.cand-head .ch-name{font-weight:700;font-size:14px}
.cand-head .ch-tag{font-size:var(--fs-small);color:var(--ink-3);margin-top:1px}
.btn-select{
  margin-left:auto;flex-shrink:0;padding:3px 10px;font-size:var(--fs-small);font-weight:600;
  border:1px solid var(--line-strong);border-radius:6px;background:var(--surface);color:var(--ink);cursor:pointer;
}
.btn-select:hover{border-color:var(--ink-2)}
.btn-select[aria-pressed="true"]{background:var(--ink);border-color:var(--ink);color:#fff}
.badge-decided{
  display:none;margin-left:auto;padding:3px 10px;border-radius:6px;font-size:var(--fs-small);font-weight:700;
  background:var(--best-bg);color:var(--best-ink);border:1px solid var(--best-line);
}

/* 总分行 */
.row-score td,.row-score th{padding-top:8px;padding-bottom:8px;background:#FCFBF7}
.row-score th[scope=row]{font-size:var(--fs-small);color:var(--ink-2);font-weight:700}
.score-num{font-size:17px;font-weight:800;letter-spacing:-.3px}
.rank-chip{
  display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;margin-left:6px;
  border-radius:50%;background:#EDEAE0;color:var(--ink-2);font-size:var(--fs-small);font-weight:700;
}
.rank-chip.r1{background:var(--ink);color:#fff}
.score-bar{display:block;height:4px;width:76px;background:#ECE9DE;border-radius:3px;margin-top:4px;overflow:hidden}
.score-bar i{display:block;height:100%;border-radius:3px}
.pill-rec{
  display:inline-block;margin-left:6px;padding:2px 8px;border-radius:999px;background:var(--ok-bg);
  color:#fff;font-size:var(--fs-small);font-weight:700;vertical-align:2px;
}

/* 分组行 */
tr.g th{
  position:sticky;left:0;font-size:var(--fs-small);font-weight:700;color:var(--ink-3);letter-spacing:1px;
  background:#F5F3EC;border-bottom:1px solid var(--line);padding:3px 10px;text-align:left;
}

/* 维度行 */
th[scope=row]{font-weight:600;font-size:var(--fs-small);color:var(--ink-2)}
th[scope=row] small{display:block;font-weight:400;color:var(--ink-3)}
.cell-val{font-weight:600}
.cell-sub{display:block;font-size:var(--fs-small);color:var(--ink-3);font-weight:400;margin-top:1px}
.mini-bar{display:block;height:3px;width:64px;background:#EFECE2;border-radius:2px;margin-top:4px;overflow:hidden}
.mini-bar i{display:block;height:100%;border-radius:2px}
.tag-best{
  display:inline-block;margin-left:6px;padding:1px 6px;border-radius:5px;font-size:var(--fs-small);font-weight:700;
  background:var(--best-bg);color:var(--best-ink);border:1px solid var(--best-line);
}
td.best{background:var(--best-bg)}
td.best .cell-val{color:var(--best-ink)}
td.best .mini-bar{background:#D2E2CC}
td.worst .cell-val{color:var(--ink-3);font-weight:500}

/* 列状态 */
#cmp td.col-sel,#cmp thead th.col-sel{background:var(--sel-bg)}
#cmp thead th.col-sel{box-shadow:inset 0 -3px 0 var(--pin,#888)}
#cmp td.col-decided,#cmp thead th.col-decided{background:var(--best-bg)}
#cmp thead th.col-decided{box-shadow:inset 0 -3px 0 var(--best-ink)}
#cmp td.col-sel.best,#cmp td.col-decided.best{background:var(--best-bg)}
#cmp td.col-decided.best .cell-val,#cmp td.col-decided.best .score-num{color:var(--best-ink)}
tr.g th.col-sel,tr.g th.col-decided{background:#F5F3EC}

/* ── 底部：权重 + 落定条 ───────────────── */
#weighbar{
  display:flex;align-items:stretch;gap:16px;padding:10px 18px;
  background:var(--surface);border-top:1px solid var(--line-strong);box-shadow:0 -2px 10px rgba(27,30,34,.04);
}
.weights{flex:1;min-width:0;display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.w-title{font-size:var(--fs-small);font-weight:700;color:var(--ink-2);letter-spacing:1px;flex-shrink:0}
.sliders{display:flex;gap:4px 16px;flex-wrap:wrap;align-items:center}
.wg{display:inline-flex;align-items:center;gap:6px}
.wg label{font-size:var(--fs-small);color:var(--ink-2);font-weight:600}
.wg output{font-size:var(--fs-small);font-weight:700;color:var(--ink);min-width:20px;text-align:right}
.wg input[type=range]{width:86px;accent-color:var(--accent);height:18px}
.presets{display:flex;gap:6px;align-items:center}
.btn-preset,.btn-ghost{
  padding:4px 10px;font-size:var(--fs-small);font-weight:600;border-radius:6px;cursor:pointer;
  border:1px solid var(--line-strong);background:var(--surface);color:var(--ink);
}
.btn-preset:hover,.btn-ghost:hover{border-color:var(--ink-2)}
.btn-preset.on{background:var(--sel-bg);border-color:var(--ink-2)}

.decide-panel{
  flex-shrink:0;display:flex;align-items:center;gap:12px;padding:8px 14px;border-radius:var(--radius);
  border:1px solid var(--line-strong);background:var(--bg);min-width:330px;max-width:46%;
}
.dp-info{min-width:0;flex:1}
.dp-title{font-size:var(--fs-small);color:var(--ink-2);font-weight:600}
.dp-main{font-size:14px;font-weight:700;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dp-reason{font-size:var(--fs-small);color:var(--ink-2);font-weight:400;margin-top:2px}
.btn-primary{
  flex-shrink:0;padding:9px 18px;border-radius:var(--radius);border:1px solid var(--ink);
  background:var(--ink);color:#fff;font-size:14px;font-weight:700;cursor:pointer;
}
.btn-primary:hover:not(:disabled){background:#000}
.btn-primary:disabled{opacity:.4;cursor:not-allowed}
.decide-panel.decided{background:var(--best-bg);border-color:var(--best-line)}
.decide-panel.decided .btn-primary{background:transparent;color:var(--best-ink);border-color:var(--best-ink);font-weight:600}

/* 致命错误（防御态，正常流程不出现） */
.fatal{
  position:fixed;inset:auto 16px 16px 16px;padding:14px 18px;border-radius:var(--radius);
  background:#7F1D1D;color:#fff;font-size:14px;box-shadow:var(--shadow);z-index:99;
}

